
.page-world {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hero h1 {
  font-family: var(--font-hand);
  font-size: 1.55rem;
  color: var(--c-primary);
}

.sub {
  color: var(--c-text-muted);
  margin-top: 4px;
}

.layout {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr;
  gap: 14px;
}

@media (max-width: 720px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.paper {
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  padding: 14px 16px;
  border-radius: 2px;
  position: relative;
}

.paper::before {
  content: '';
  position: absolute;
  inset: 8px auto auto 0;
  width: 100%;
  height: calc(100% - 16px);
  background-image: repeating-linear-gradient(
    transparent,
    transparent 27px,
    rgba(120, 150, 190, 0.22) 28px
  );
  pointer-events: none;
  opacity: 0.55;
}

.letter h2 {
  font-size: 1rem;
  margin-bottom: 8px;
  position: relative;
  z-index: 1;
}

.typewriter {
  position: relative;
  z-index: 1;
  min-height: 8.5em;
  white-space: pre-wrap;
}

.typewriter:not(.done)::after {
  content: '▌';
  color: var(--c-primary);
  animation: blink 1s step-end infinite;
}

@keyframes blink {
  50% {
    opacity: 0;
  }
}

.postcards {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.card {
  width: min(100%, 220px);
  background: #fff;
  padding: 8px 8px 12px;
  box-shadow: var(--shadow-paper);
  transform: rotate(var(--r, 0deg));
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.card:hover {
  transform: rotate(var(--r, 0deg)) translateY(-6px) scale(1.02);
  box-shadow: var(--shadow-lift);
  z-index: 2;
}

.photo {
  height: 110px;
  border-radius: 2px;
  background-size: cover;
  background-position: center;
}

.home-photo {
  background-image: linear-gradient(160deg, #c97b4a, #e8c07a 40%, #6d9a78 75%);
}

.city-photo {
  background-image: linear-gradient(160deg, #4a6078, #8aa0b8 35%, #c45c4a 70%, #2a3545);
}

.card figcaption {
  margin-top: 8px;
  font-size: 12px;
  font-weight: 700;
  text-align: center;
}

.dash {
  font-size: 11px;
  color: var(--c-text-muted);
  border-left: 2px dashed var(--c-border);
  padding-left: 8px;
  align-self: flex-start;
  margin-left: 24px;
}

.notes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

@media (max-width: 720px) {
  .notes {
    grid-template-columns: 1fr;
  }
}

.sticky {
  padding: 12px 10px;
  font-size: 12px;
  box-shadow: var(--shadow-paper);
  transform: rotate(var(--r, 0deg));
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

.sticky:hover {
  transform: rotate(var(--r, 0deg)) translateY(-5px);
  box-shadow: var(--shadow-lift);
}

.sticky.green {
  background: var(--c-surface-note-green);
}
.sticky.yellow {
  background: var(--c-surface-note);
}
.sticky.coral {
  background: var(--c-surface-note-coral);
}

.wobble {
  animation: wobble 3.6s ease-in-out infinite;
}

@keyframes wobble {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: 0 -2px;
  }
}

.actions {
  display: flex;
  justify-content: center;
  padding-top: 8px;
}

.btn-primary {
  background: var(--c-primary);
  color: #f7f2e8;
  border: 2px solid #1f3d31;
  padding: 10px 18px;
  border-radius: 4px;
  font-weight: 700;
  letter-spacing: 0.02em;
  box-shadow: 2px 3px 0 rgba(30, 40, 30, 0.25);
}

.btn-primary:hover {
  background: var(--c-primary-soft);
}
