
.steps {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 8px 4px 16px;
  flex-wrap: wrap;
}

.step {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-text-muted);
  position: relative;
}

.dot {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid var(--c-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  background: var(--c-surface-paper);
}

.label {
  font-size: 12px;
  white-space: nowrap;
}

.line {
  width: 28px;
  height: 2px;
  background: var(--c-border);
  margin: 0 4px;
}

.step.active .dot,
.step.done .dot {
  background: var(--c-accent);
  border-color: var(--c-accent);
  color: #fff;
}

.step.active .label {
  color: var(--c-text);
  font-weight: 700;
}

.step.done .line {
  background: var(--c-accent);
}
