
.page-story {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hero h1 {
  font-size: 1.35rem;
  color: var(--c-primary);
}
.sub {
  color: var(--c-text-muted);
  font-size: 12px;
}

.layout {
  display: grid;
  grid-template-columns: 1.25fr 0.95fr;
  gap: 12px;
}

@media (max-width: 820px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.paper {
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  padding: 10px;
}

.map {
  position: relative;
  min-height: 320px;
  border-radius: 4px;
  background: #d9c7a8 center / cover no-repeat;
  overflow: hidden;
}

.map-hint {
  margin-top: 6px;
  font-size: 11px;
  color: var(--c-text-muted);
  text-align: center;
}

.pin {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: none;
  color: var(--c-text);
}

.pin.home {
  left: 18%;
  bottom: 22%;
}
.pin.uni {
  right: 16%;
  top: 18%;
}

.pin-head {
  width: 34px;
  height: 34px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: #c45c4a;
  color: #fff;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.25);
}

.pin-head {
  font-size: 12px;
  line-height: 1;
}

.pin-label {
  background: rgba(255, 250, 240, 0.92);
  border: 1px solid var(--c-border);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
}

.pin.on .pin-head {
  background: var(--c-primary);
  outline: 2px solid var(--c-accent);
}

.side h2 {
  font-size: 0.95rem;
  margin-bottom: 8px;
}

.tag {
  font-weight: 700;
  margin-bottom: 8px;
}

.hint {
  font-size: 12px;
  color: var(--c-text-muted);
  margin-bottom: 8px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 10px;
}
.field > span {
  font-size: 12px;
  font-weight: 700;
  color: var(--c-text-muted);
}

input,
textarea {
  border: 1px solid var(--c-border);
  background: rgba(255, 255, 255, 0.8);
  border-radius: 4px;
  padding: 7px 9px;
}

.pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.pill {
  border: 1px solid var(--c-border);
  background: #fff;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 12px;
}
.pill.on {
  background: var(--c-primary);
  color: #fff;
  border-color: var(--c-primary);
}

.custom-roomie {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}
.custom-roomie .row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.btn-primary,
.btn-ghost,
.btn-dashed {
  padding: 9px 14px;
  border-radius: 4px;
  font-weight: 700;
}
.btn-primary {
  background: var(--c-primary);
  color: #f7f2e8;
  border: 2px solid #1f3d31;
}
.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.btn-ghost {
  background: transparent;
  border: 1px solid var(--c-border);
}
.btn-dashed {
  background: #fff;
  border: 1.5px dashed var(--c-primary);
  color: var(--c-primary);
}
