
.page-profile {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hero h1 {
  font-size: 1.35rem;
  color: var(--c-primary);
}

.layout {
  display: grid;
  grid-template-columns: 1.15fr 0.95fr;
  gap: 12px;
}

@media (max-width: 720px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.paper,
.note {
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  padding: 14px;
}

.note {
  background: var(--c-surface-note);
  transform: rotate(0.4deg);
}

h2 {
  font-size: 0.95rem;
  margin-bottom: 10px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 10px;
}

.field > span {
  font-size: 12px;
  font-weight: 700;
  color: var(--c-text-muted);
}

input,
textarea {
  border: 1px solid var(--c-border);
  background: rgba(255, 255, 255, 0.75);
  border-radius: 4px;
  padding: 7px 9px;
  outline: none;
}

input:focus,
textarea:focus {
  border-color: var(--c-primary);
}

.pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.pill {
  border: 1px solid var(--c-border);
  background: #fff;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 12px;
}

.pill.on {
  background: var(--c-primary);
  border-color: var(--c-primary);
  color: #fff;
}

.pill.dashed {
  border-style: dashed;
}

.mt {
  margin-top: 6px;
}

.err {
  color: var(--c-danger);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding-top: 4px;
}

.btn-primary,
.btn-ghost,
.btn-dashed {
  padding: 9px 14px;
  border-radius: 4px;
  font-weight: 700;
}

.btn-primary {
  background: var(--c-primary);
  color: #f7f2e8;
  border: 2px solid #1f3d31;
}

.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-ghost {
  background: transparent;
  border: 1px solid var(--c-border);
}

.btn-dashed {
  background: #fff;
  border: 1.5px dashed var(--c-primary);
  color: var(--c-primary);
}
